// Built-in "Premade worlds" tab options (see App.tsx's Generate World dialog) -- each is a
// coastline sketch in the same white-background/black-outline convention "Human-made" mode
// expects (see worldsketch.py's module docstring), pre-baked as a data URL so picking one
// behaves exactly like drawing or loading an image did: it just becomes `sketchImageDataUrl`
// and rides the existing Human-made generation path (see handleGenerate).
//
// "Present-day Earth" traces real (Natural Earth 110m) coastlines, plus real major mountain
// belts (Rockies, Andes, Alps-Himalaya, etc, hand-picked ridgelines -- Natural Earth has no
// simple mountain-centerline layer at this scale) and real major rivers (Natural Earth 50m
// river centerlines, scalerank <= 3: Amazon, Nile, Mississippi/Missouri, Yangtze, ...) in the
// ink convention's mountain/river colors, so the generated world gets realistic elevation and
// river placement, not just a coastline.
//
// "Pangaea (pre-breakup)" reassembles real Natural Earth continent outlines (Africa+Eurasia
// and North+South America each split at their present-day land bridge -- Suez, Panama -- via
// pangaea_lib.split_ring) into the classic Wegener/du Toit "C"-shaped supercontinent fit
// (Laurasia/Gondwana wrapped around the Tethys), via simple planar rotate+translate per piece
// -- not real Euler-pole paleogeographic reconstruction data, so treat it as directionally
// right (which real coastlines nest against which) rather than scientifically exact. Antarctica
// is a stylized blob rather than its real (polar-flattened, not meaningful under a planar
// rotation) dataset shape.
//
// "Dragons & Zombie World" is an original, hand-drawn interpretation of a well-known fantasy
// world's known geography (relative sizes and named features of its three continents,
// gathered from public wiki descriptions) -- not a trace of any copyrighted map artwork.
//
// Every world's seed (below) is fixed, not left to whatever the Seed field last held: the same
// sketch can reconstruct very differently depending on plate seed, so each was picked by
// generating every seed 1-30 against that world's own sketch and keeping the one whose
// generated land/sea agrees best with the sketch's flood-filled land mask (see the git history
// for the search script) -- not hand-tuned or otherwise special beyond that.

export interface PremadeWorld {
  id: string;
  label: string;
  dataUrl: string;
  seed: number;
}

const EARTH_PNG_B64 =
  "";

const PANGAEA_PNG_B64 =
  "";

const GOT_PNG_B64 =
  "";

export const PREMADE_WORLDS: PremadeWorld[] = [
  { id: "earth", label: "Present-day Earth", dataUrl: `data:image/png;base64,${EARTH_PNG_B64}`, seed: 8 },
  { id: "pangaea", label: "Pangaea (pre-breakup)", dataUrl: `data:image/png;base64,${PANGAEA_PNG_B64}`, seed: 26 },
  { id: "got", label: "Dragons & Zombie World", dataUrl: `data:image/png;base64,${GOT_PNG_B64}`, seed: 10 },
];
